begin;
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','vendor','runner','admin');
create type public.order_state as enum ('DRAFT','PENDING_PAYMENT','PAID','VENDOR_ACCEPTED','RUNNER_MATCHING','RUNNER_ASSIGNED','READY_FOR_PICKUP','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED','COMPLETED','CANCELLED');
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text not null default 'Neighbor',suspended boolean not null default false,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid references public.profiles on delete cascade,role public.app_role,primary key(user_id,role));
create table public.vendors(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles,name text not null,slug text unique not null,description text not null default '',category text not null,public_lon numeric not null,public_lat numeric not null,demo boolean not null default true,verified boolean not null default false,active boolean not null default true,hours jsonb not null default '{}',service_area text not null default '');
create table public.vendor_private(vendor_id uuid primary key references public.vendors on delete cascade,pickup_address text not null,pickup_lon numeric,pickup_lat numeric);
create table public.listings(id uuid primary key default gen_random_uuid(),vendor_id uuid not null references public.vendors,title text not null,description text not null default '',category text not null,mode text not null check(mode in ('SELL','MAKE','DO')),price_cents bigint not null check(price_cents between 0 and 10000000),inventory integer not null check(inventory>=0),made_local boolean not null default false,active boolean not null default true,prohibited boolean not null default false,emoji text not null default '⌂',photos text[] not null default '{}');
create table public.runners(id uuid primary key references public.profiles,display_name text not null default 'Runner',bio text not null default '',public_lon numeric not null,public_lat numeric not null,available_until timestamptz,categories text[] not null default '{}',max_detour_miles numeric not null default 3 check(max_detour_miles between 0 and 50),visible boolean not null default false,reliability numeric not null default 1 check(reliability between 0 and 1),completed_runs integer not null default 0,reward_points bigint not null default 0);
create table public.runner_trips(id uuid primary key default gen_random_uuid(),runner_id uuid not null references public.runners,destination_vendor_id uuid references public.vendors,expires_at timestamptz not null,note text not null default '');
create table public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.profiles,listing_id uuid not null references public.listings,vendor_id uuid not null references public.vendors,runner_id uuid references public.runners,quantity integer not null check(quantity between 1 and 20),unit_price_cents bigint not null,total_cents bigint not null check(total_cents>=0),state public.order_state not null default 'DRAFT',request_key uuid not null,paypal_order_id text unique,paypal_capture_id text unique,payout_status text not null default 'SIMULATED' check(payout_status='SIMULATED'),created_at timestamptz not null default now(),unique(customer_id,request_key));
create table public.order_private(order_id uuid primary key references public.orders,delivery_address text not null);
create table public.order_events(id bigint generated always as identity primary key,order_id uuid not null references public.orders,actor_id uuid references public.profiles,event text not null,created_at timestamptz not null default now());
create table public.payment_events(event_id text primary key,order_id uuid not null references public.orders,capture_id text not null,created_at timestamptz not null default now());
create table public.ledger(id bigint generated always as identity primary key,order_id uuid not null references public.orders,kind text not null check(kind in ('CUSTOMER_PAYMENT','VENDOR_ALLOCATION','RUNNER_ALLOCATION','PLATFORM_ALLOCATION','REFUND','ADJUSTMENT')),amount_cents bigint not null,simulated boolean not null default true,created_at timestamptz not null default now(),unique(order_id,kind));
create table public.audit_events(id bigint generated always as identity primary key,actor_id uuid,event text not null,resource_id uuid,created_at timestamptz not null default now());
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles,listing_id uuid references public.listings,reason text not null check(length(reason) between 5 and 1000),resolved boolean not null default false,created_at timestamptz not null default now());
create table public.blocks(user_id uuid references public.profiles,blocked_user_id uuid references public.profiles,primary key(user_id,blocked_user_id),check(user_id<>blocked_user_id));
create table public.rate_limits(user_id uuid references public.profiles,action text,window_start timestamptz,count integer not null,primary key(user_id,action,window_start));
create function public.has_role(wanted public.app_role) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles r join public.profiles p on p.id=r.user_id where r.user_id=auth.uid() and r.role=wanted and not p.suspended); $$;
create function public.account_active() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles where id=auth.uid() and not suspended); $$;
create function public.owns_vendor(v uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.account_active() and public.has_role('vendor') and exists(select 1 from public.vendors where id=v and owner_id=auth.uid()); $$;
create function public.order_access(o uuid) returns boolean language sql stable security definer set search_path='' as $$ select public.account_active() and exists(select 1 from public.orders where id=o and (customer_id=auth.uid() or runner_id=auth.uid() or public.owns_vendor(vendor_id) or public.has_role('admin'))); $$;
create function public.profile_enabled(p uuid) returns boolean language sql stable security definer set search_path='' as $$ select p is null or exists(select 1 from public.profiles where id=p and not suspended); $$;
create function public.new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id) values(new.id);insert into public.user_roles values(new.id,'customer');return new;end; $$;
create trigger user_created after insert on auth.users for each row execute function public.new_user();
-- Coarsen public coordinates in the database even if a client submits GPS precision.
create function public.coarsen_location() returns trigger language plpgsql set search_path='' as $$ begin new.public_lon=round(new.public_lon,2);new.public_lat=round(new.public_lat,2);return new;end; $$;
create trigger coarsen_runner before insert or update on public.runners for each row execute function public.coarsen_location();
create trigger coarsen_vendor before insert or update on public.vendors for each row execute function public.coarsen_location();
-- Only identifiers are audited; addresses, descriptions and coordinates never enter audit logs.
create function public.audit_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.audit_events(actor_id,event,resource_id) values(auth.uid(),tg_table_name||'_'||tg_op,case when tg_table_name='user_roles' then (to_jsonb(new)->>'user_id')::uuid else (to_jsonb(new)->>'id')::uuid end);return new;end; $$;
create trigger vendor_audit after insert or update on public.vendors for each row execute function public.audit_change();
create trigger listing_audit after insert or update on public.listings for each row execute function public.audit_change();
create trigger runner_audit after insert or update on public.runners for each row execute function public.audit_change();
create trigger roles_audit after insert or update on public.user_roles for each row execute function public.audit_change();
-- All public-schema tables have RLS. Financial state has no direct client write grants.
do $$ declare t text;begin foreach t in array array['profiles','user_roles','vendors','vendor_private','listings','runners','runner_trips','orders','order_private','order_events','payment_events','ledger','audit_events','reports','blocks','rate_limits'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.has_role('admin'));
create policy profile_edit on public.profiles for update to authenticated using(id=auth.uid() and public.account_active()) with check(id=auth.uid());
create policy roles_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.has_role('admin'));
create policy vendors_read on public.vendors for select using((active and public.profile_enabled(owner_id)) or public.owns_vendor(id) or public.has_role('admin'));
create policy vendor_edit on public.vendors for update to authenticated using(public.owns_vendor(id)) with check(public.owns_vendor(id));
create policy private_vendor_read on public.vendor_private for select to authenticated using(public.owns_vendor(vendor_id) or public.has_role('admin') or exists(select 1 from public.orders where orders.vendor_id=vendor_private.vendor_id and runner_id=auth.uid() and state in ('RUNNER_ASSIGNED','READY_FOR_PICKUP','PICKED_UP','OUT_FOR_DELIVERY')));
create policy listings_read on public.listings for select using((active and not prohibited and exists(select 1 from public.vendors where id=vendor_id and active and public.profile_enabled(owner_id))) or public.owns_vendor(vendor_id) or public.has_role('admin'));
create policy listing_edit on public.listings for update to authenticated using(public.owns_vendor(vendor_id)) with check(public.owns_vendor(vendor_id));
create policy runner_read on public.runners for select using((visible and available_until>now() and public.profile_enabled(id)) or id=auth.uid() or public.has_role('admin'));
create policy runner_edit on public.runners for update to authenticated using(id=auth.uid() and public.has_role('runner')) with check(id=auth.uid());
create policy trips_read on public.runner_trips for select using((expires_at>now() and exists(select 1 from public.runners where id=runner_id and visible and available_until>now())) or runner_id=auth.uid() or public.has_role('admin'));
create policy trips_insert on public.runner_trips for insert to authenticated with check(runner_id=auth.uid() and public.has_role('runner') and expires_at>now() and expires_at<now()+interval '12 hours');
create policy orders_read on public.orders for select to authenticated using(public.order_access(id));
create policy order_private_read on public.order_private for select to authenticated using(public.account_active() and exists(select 1 from public.orders where id=order_id and (customer_id=auth.uid() or (runner_id=auth.uid() and state in ('RUNNER_ASSIGNED','READY_FOR_PICKUP','PICKED_UP','OUT_FOR_DELIVERY')))));
create policy order_private_insert on public.order_private for insert to authenticated with check(exists(select 1 from public.orders where id=order_id and customer_id=auth.uid() and state='DRAFT') and public.account_active());
create policy events_read on public.order_events for select to authenticated using(public.order_access(order_id));
create policy payment_read on public.payment_events for select to authenticated using(public.has_role('admin'));
create policy ledger_read on public.ledger for select to authenticated using(public.order_access(order_id));
create policy audit_read on public.audit_events for select to authenticated using(public.has_role('admin'));
create policy report_read on public.reports for select to authenticated using(reporter_id=auth.uid() or public.has_role('admin'));
create policy report_insert on public.reports for insert to authenticated with check(reporter_id=auth.uid() and public.account_active());
create policy block_read on public.blocks for select to authenticated using(user_id=auth.uid());
create policy block_insert on public.blocks for insert to authenticated with check(user_id=auth.uid() and public.account_active());
revoke all on all tables in schema public from anon,authenticated;
grant select on public.vendors,public.listings,public.runners,public.runner_trips to anon,authenticated;
grant select on public.profiles,public.user_roles,public.vendor_private,public.orders,public.order_private,public.order_events,public.payment_events,public.ledger,public.audit_events,public.reports,public.blocks to authenticated;
grant update(display_name) on public.profiles to authenticated;
grant update(name,description,hours,service_area) on public.vendors to authenticated;
grant update(title,description,price_cents,inventory,active,made_local) on public.listings to authenticated;
grant update(bio,public_lon,public_lat,available_until,categories,max_detour_miles,visible) on public.runners to authenticated;
grant insert on public.runner_trips,public.order_private,public.reports,public.blocks to authenticated;
create function public.consume_rate_limit(action_name text) returns void language plpgsql security definer set search_path='' as $$ declare n integer;begin if not public.account_active() or length(action_name)>40 then raise exception 'Unauthorized';end if;insert into public.rate_limits values(auth.uid(),action_name,date_trunc('minute',now()),1) on conflict(user_id,action,window_start) do update set count=public.rate_limits.count+1 returning count into n;if n>20 then raise exception 'Rate limit exceeded';end if;end; $$;
create function public.prepare_order(listing_id uuid,qty integer,request_key uuid,delivery_address text default null) returns public.orders language plpgsql security definer set search_path='' as $$ declare l public.listings;o public.orders;begin if not public.account_active() or qty not between 1 and 20 then raise exception 'Unauthorized or invalid quantity';end if;if delivery_address is not null and length(delivery_address) not between 8 and 500 then raise exception 'Invalid delivery address';end if;perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||request_key::text,0));select * into o from public.orders where customer_id=auth.uid() and orders.request_key=prepare_order.request_key;if found then return o;end if;select * into l from public.listings where id=listing_id for update;if not found or not l.active or l.prohibited or l.inventory<qty or not exists(select 1 from public.vendors where id=l.vendor_id and active and public.profile_enabled(owner_id)) then raise exception 'Unavailable';end if;update public.listings set inventory=inventory-qty where id=l.id;insert into public.orders(customer_id,listing_id,vendor_id,quantity,unit_price_cents,total_cents,request_key) values(auth.uid(),l.id,l.vendor_id,qty,l.price_cents,l.price_cents*qty,request_key) returning * into o;insert into public.order_events(order_id,actor_id,event) values(o.id,auth.uid(),'ORDER_CREATED');if delivery_address is not null then insert into public.order_private values(o.id,delivery_address);end if;return o;end; $$;
create function public.attach_paypal_order(order_id uuid,paypal_id text) returns void language plpgsql security definer set search_path='' as $$ declare o public.orders;begin select * into o from public.orders where id=order_id for update;if not found or not public.account_active() or o.customer_id<>auth.uid() or o.state not in ('DRAFT','PENDING_PAYMENT') or (o.paypal_order_id is not null and o.paypal_order_id<>paypal_id) then raise exception 'Unauthorized';end if;if length(paypal_id)>100 then raise exception 'Invalid identifier';end if;update public.orders set paypal_order_id=paypal_id,state='PENDING_PAYMENT' where id=o.id;insert into public.order_events(order_id,actor_id,event) values(o.id,auth.uid(),'PAYMENT_PENDING');end; $$;
create function public.confirm_payment(order_id uuid,capture_id text,event_id text,amount_cents bigint) returns void language plpgsql security definer set search_path='' as $$ declare o public.orders;v bigint;r bigint;begin select * into o from public.orders where id=order_id for update;if not found or o.total_cents<>amount_cents then raise exception 'Payment mismatch';end if;if o.paypal_capture_id=capture_id then insert into public.payment_events values(event_id,o.id,capture_id,now()) on conflict do nothing;return;end if;if o.state<>'PENDING_PAYMENT' or o.paypal_order_id is null then raise exception 'Not payable';end if;insert into public.payment_events values(event_id,o.id,capture_id,now());update public.orders set state='PAID',paypal_capture_id=capture_id where id=o.id;v=o.total_cents*80/100;r=o.total_cents*15/100;insert into public.ledger(order_id,kind,amount_cents,simulated) values(o.id,'CUSTOMER_PAYMENT',o.total_cents,false),(o.id,'VENDOR_ALLOCATION',v,true),(o.id,'RUNNER_ALLOCATION',r,true),(o.id,'PLATFORM_ALLOCATION',o.total_cents-v-r,true);insert into public.order_events(order_id,event) values(o.id,'PAYMENT_CONFIRMED');end; $$;
create function public.transition_order(order_id uuid,target_state public.order_state) returns public.orders language plpgsql security definer set search_path='' as $$ declare o public.orders;expected public.order_state;begin if not public.account_active() then raise exception 'Unauthorized';end if;select * into o from public.orders where id=order_id for update;if not found then raise exception 'Unknown order';end if;expected=case o.state when 'PAID' then 'VENDOR_ACCEPTED'::public.order_state when 'VENDOR_ACCEPTED' then 'RUNNER_MATCHING'::public.order_state when 'RUNNER_ASSIGNED' then 'READY_FOR_PICKUP'::public.order_state when 'READY_FOR_PICKUP' then 'PICKED_UP'::public.order_state when 'PICKED_UP' then 'OUT_FOR_DELIVERY'::public.order_state when 'OUT_FOR_DELIVERY' then 'DELIVERED'::public.order_state when 'DELIVERED' then 'COMPLETED'::public.order_state else null end;
if expected is null or target_state<>expected then raise exception 'Invalid transition';end if;
if target_state in ('VENDOR_ACCEPTED','RUNNER_MATCHING','READY_FOR_PICKUP') then if not public.owns_vendor(o.vendor_id) then raise exception 'Vendor required';end if;
elsif target_state in ('PICKED_UP','OUT_FOR_DELIVERY','DELIVERED') then if o.runner_id is distinct from auth.uid() or not public.has_role('runner') then raise exception 'Assigned runner required';end if;
elsif target_state='COMPLETED' then if o.customer_id<>auth.uid() then raise exception 'Customer required';end if;end if;
update public.orders set state=target_state where id=o.id returning * into o;insert into public.order_events(order_id,actor_id,event) values(o.id,auth.uid(),target_state::text);if target_state='COMPLETED' then update public.runners set completed_runs=completed_runs+1,reward_points=reward_points+10 where id=o.runner_id;end if;return o;end; $$;
create function public.accept_run(order_id uuid) returns public.orders language plpgsql security definer set search_path='' as $$ declare o public.orders;r public.runners;l public.listings;begin if not public.has_role('runner') then raise exception 'Runner required';end if;select * into r from public.runners where id=auth.uid() for update;select * into o from public.orders where id=order_id for update;if not found or o.state<>'RUNNER_MATCHING' or r.available_until is null or r.available_until<=now() then raise exception 'Unavailable';end if;select * into l from public.listings where id=o.listing_id;if not l.category=any(r.categories) then raise exception 'Incompatible category';end if;if (select count(*) from public.orders where runner_id=r.id and state in ('RUNNER_ASSIGNED','READY_FOR_PICKUP','PICKED_UP','OUT_FOR_DELIVERY'))>=3 then raise exception 'Workload exceeded';end if;update public.orders set runner_id=r.id,state='RUNNER_ASSIGNED' where id=o.id returning * into o;insert into public.order_events(order_id,actor_id,event) values(o.id,auth.uid(),'RUNNER_ASSIGNED');return o;end; $$;
create function public.available_runs() returns table(id uuid,vendor_name text,category text,public_lon numeric,public_lat numeric) language sql stable security definer set search_path='' as $$ select o.id,v.name,l.category,v.public_lon,v.public_lat from public.orders o join public.vendors v on v.id=o.vendor_id join public.listings l on l.id=o.listing_id where o.state='RUNNER_MATCHING' and public.has_role('runner'); $$;
create function public.cancel_draft(order_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare o public.orders;begin select * into o from public.orders where id=order_id for update;if not found or o.customer_id<>auth.uid() or not public.account_active() or o.state<>'DRAFT' or o.paypal_order_id is not null then raise exception 'Cannot cancel';end if;update public.listings set inventory=inventory+o.quantity where id=o.listing_id;update public.orders set state='CANCELLED' where id=o.id;insert into public.order_events(order_id,actor_id,event) values(o.id,auth.uid(),'ORDER_CANCELLED');end; $$;
create function public.moderate(resource_type text,resource_id uuid,disabled boolean) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_role('admin') then raise exception 'Admin required';end if;if resource_type='profile' then update public.profiles set suspended=disabled where id=resource_id;elsif resource_type='listing' then update public.listings set active=not disabled where id=resource_id;elsif resource_type='vendor' then update public.vendors set active=not disabled where id=resource_id;else raise exception 'Invalid resource';end if;insert into public.audit_events(actor_id,event,resource_id) values(auth.uid(),'MODERATION_'||resource_type,resource_id);end; $$;
create function public.runner_workloads() returns table(runner_id uuid,workload bigint) language sql stable security definer set search_path='' as $$ select r.id,count(o.id) from public.runners r left join public.orders o on o.runner_id=r.id and o.state in ('RUNNER_ASSIGNED','READY_FOR_PICKUP','PICKED_UP','OUT_FOR_DELIVERY') where r.visible and r.available_until>now() and public.profile_enabled(r.id) group by r.id; $$;
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.runner_workloads(),public.profile_enabled(uuid),public.has_role(public.app_role),public.account_active(),public.owns_vendor(uuid),public.order_access(uuid) to anon,authenticated;
grant execute on function public.consume_rate_limit(text),public.prepare_order(uuid,integer,uuid,text),public.attach_paypal_order(uuid,text),public.transition_order(uuid,public.order_state),public.accept_run(uuid),public.available_runs(),public.cancel_draft(uuid),public.moderate(text,uuid,boolean) to authenticated;
grant execute on function public.confirm_payment(uuid,text,text,bigint) to service_role;
commit;
